--// VaDaa Ultimate Universal + Game Scripts Rayfield Paneli    

-- Rayfield yükleme    
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()    

local Window = Rayfield:CreateWindow({    
Name = "My Control Panel ⚙️",    
LoadingTitle = "Hi...",    
LoadingSubtitle = "Hazırlanıyor...",    
ConfigurationSaving = { Enabled = false },    
KeySystem = false,    
})    


